Here are the changes to add the user role update functionality:

### 1. Create the API Hook (`update-user-role.ts`)
This file defines the API call and the React Query mutation hook, which automatically invalidates the user list on success.

**`apps/react-vite/src/features/users/api/update-user-role.ts`**
```typescript
import { useMutation, useQueryClient } from '@tanstack/react-query';

import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';

import { getUsersQueryOptions } from './get-users';

export type UpdateUserRoleDTO = {
  userId: string;
  role: 'ADMIN' | 'USER';
};

export const updateUserRole = ({ userId, role }: UpdateUserRoleDTO) => {
  return api.patch(`/users/${userId}/role`, { role });
};

type UseUpdateUserRoleOptions = {
  mutationConfig?: MutationConfig<typeof updateUserRole>;
};

export const useUpdateUserRole = ({
  mutationConfig,
}: UseUpdateUserRoleOptions = {}) => {
  const queryClient = useQueryClient();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      queryClient.invalidateQueries({
        queryKey: getUsersQueryOptions().queryKey,
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateUserRole,
  });
};
```

### 2. Update the Users List Component (`users-list.tsx`)
This component now includes a role `<select>` dropdown for every user row. It triggers the mutation, shows a success notification, and the table updates automatically.

**`apps/react-vite/src/features/users/components/users-list.tsx`**
```typescript
import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';
import { useNotifications } from '@/components/ui/notifications';

import { useUsers } from '../api/get-users';
import { useUpdateUserRole } from '../api/update-user-role';

import { DeleteUser } from './delete-user';

export const UsersList = () => {
  const usersQuery = useUsers();
  const { addNotification } = useNotifications();
  const updateUserRoleMutation = useUpdateUserRole({
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'User role updated',
        });
      },
    },
  });

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  return (
    <Table
      data={users}
      columns={[
        {
          title: 'First Name',
          field: 'firstName',
        },
        {
          title: 'Last Name',
          field: 'lastName',
        },
        {
          title: 'Email',
          field: 'email',
        },
        {
          title: 'Role',
          field: 'role',
          Cell({ entry: { id, role } }) {
            return (
              <select
                value={role}
                onChange={(e) => {
                  updateUserRoleMutation.mutate({
                    userId: id,
                    role: e.target.value as 'ADMIN' | 'USER',
                  });
                }}
                className="rounded border-gray-300 bg-white p-1 text-sm"
                disabled={updateUserRoleMutation.isPending}
              >
                <option value="ADMIN">ADMIN</option>
                <option value="USER">USER</option>
              </select>
            );
          },
        },
        {
          title: 'Created At',
          field: 'createdAt',
          Cell({ entry: { createdAt } }) {
            return <span>{formatDate(createdAt)}</span>;
          },
        },
        {
          title: '',
          field: 'id',
          Cell({ entry: { id } }) {
            return <DeleteUser id={id} />;
          },
        },
      ]}
    />
  );
};
```

### 3. Add the MSW Handler (`handlers/users.ts`)
This adds the mock API endpoint to handle the `PATCH` request for updating roles.

**`apps/react-vite/src/testing/mocks/handlers/users.ts`**
```typescript
import { HttpResponse, http } from 'msw';

import { env } from '@/config/env';

import { db, persistDb } from '../db';
import {
  requireAuth,
  requireAdmin,
  sanitizeUser,
  networkDelay,
} from '../utils';

type ProfileBody = {
  email: string;
  firstName: string;
  lastName: string;
  bio: string;
};

export const usersHandlers = [
  http.get(`${env.API_URL}/users`, async ({ cookies }) => {
    // ... existing get handler ...
    // (omitted for brevity, original content remains)
  }),

  // ... existing patch profile handler ...

  http.patch(
    `${env.API_URL}/users/:userId/role`,
    async ({ request, params, cookies }) => {
      await networkDelay();

      try {
        const { user, error } = requireAuth(cookies);
        if (error) {
          return HttpResponse.json({ message: error }, { status: 401 });
        }
        requireAdmin(user);
        const data = (await request.json()) as { role: string };
        const result = db.user.update({
          where: {
            id: {
              equals: params.userId as string,
            },
          },
          data: { role: data.role },
        });
        await persistDb('user');
        return HttpResponse.json(sanitizeUser(result));
      } catch (error: any) {
        return HttpResponse.json(
          { message: error?.message || 'Server Error' },
          { status: 500 },
        );
      }
    },
  ),
];
```
